package com.bank.critical;

public class ImpactAssessment {
    private final int affectedUsers;
    private final String regions;
    private final int minutesSinceStart;
    private final boolean worsening;

    public ImpactAssessment(int affectedUsers, String regions,
                            int minutesSinceStart, boolean worsening) {
        this.affectedUsers = affectedUsers;
        this.regions = regions;
        this.minutesSinceStart = minutesSinceStart;
        this.worsening = worsening;
    }

    public int getAffectedUsers() { return affectedUsers; }
    public String getRegions() { return regions; }
    public int getMinutesSinceStart() { return minutesSinceStart; }
    public boolean isWorsening() { return worsening; }

    public String severity() {
        return affectedUsers > 10_000 ? "SEV1" : affectedUsers > 1000 ? "SEV2" : "SEV3";
    }
}
