package com.bank.critical;

import java.util.List;
import java.util.logging.Logger;

public class IncidentResponder {
    private static final Logger log = Logger.getLogger(IncidentResponder.class.getName());

    // Step 1: confirm + size impact (user-facing signals, not "pod is up").
    public void sizeImpact(ImpactAssessment impact) {
        log.severe(() -> "[1 IMPACT] " + impact.severity() + " — " + impact.getAffectedUsers()
            + " users in " + impact.getRegions() + ", " + impact.getMinutesSinceStart()
            + "min in, worsening=" + impact.isWorsening());
    }

    // Step 2: find WHAT CHANGED most recently (prime suspect).
    public ChangeEvent findRecentChange(List<ChangeEvent> changes) {
        ChangeEvent suspect = changes.stream()
            .min((a, b) -> Integer.compare(a.getMinutesAgo(), b.getMinutesAgo()))
            .orElseThrow();
        log.warning(() -> "[2 WHAT CHANGED] prime suspect: '" + suspect.getDescription()
            + "' " + suspect.getMinutesAgo() + "min ago, reversible=" + suspect.isReversible());
        return suspect;
    }

    // Step 3: MITIGATE FIRST — rollback is fastest safe mitigation if reversible.
    public void mitigate(ChangeEvent suspect) {
        if (suspect.isReversible()) {
            log.info(() -> "[3 MITIGATE] ROLLBACK '" + suspect.getDescription()
                + "' → known-good state. Service restoring. (No root-cause needed yet.)");
        } else {
            log.info(() -> "[3 MITIGATE] not reversible → fail over / flag off / scale out / "
                + "shed load to stop the bleeding.");
        }
    }

    // Step 4: communicate (runs throughout).
    public void communicate(String update) {
        log.info(() -> "[4 COMMS] status page + stakeholders: " + update);
    }

    // Step 5: deep root-cause — ONLY after service restored.
    public void rootCauseAfterRestore() {
        log.info("[5 ROOT CAUSE] service stable → now safe to investigate calmly + write "
            + "blameless postmortem with preventive action items.");
    }
}
