package com.bank.critical;

import java.util.List;
import java.util.logging.*;

public class CriticalIncidentDemo {
    private static final Logger log = Logger.getLogger(CriticalIncidentDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        IncidentResponder responder = new IncidentResponder();

        log.severe("CRITICAL INCIDENT reported: customers cannot complete transfers");

        // Step 1: size impact
        ImpactAssessment impact = new ImpactAssessment(22_000, "all-India", 6, true);
        responder.sizeImpact(impact);
        responder.communicate("Investigating transfer failures affecting many customers (SEV1).");

        // Step 2: what changed
        ChangeEvent suspect = responder.findRecentChange(List.of(
            new ChangeEvent("transfer-service deploy v6.0", 7, true),
            new ChangeEvent("nightly batch job started", 40, false),
            new ChangeEvent("feature flag instant-transfer 10%→50%", 90, true)));

        // Step 3: MITIGATE FIRST (before any deep analysis)
        responder.mitigate(suspect);
        responder.communicate("Mitigation applied (rolled back recent deploy); service recovering.");

        // Step 4: confirm restore
        responder.communicate("Service restored; monitoring for stability.");

        // Step 5: ONLY NOW root-cause
        responder.rootCauseAfterRestore();
    }
}
